#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=5

INFRA_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
ENV_FILE="$INFRA_DIR/scripts/.env"
GV_DIR="$INFRA_DIR/inventory/group_vars/all"
OVERRIDES="$GV_DIR/zz-local.yml"
USERS_FILE="$GV_DIR/users.yml"
VAULT_FILE="$GV_DIR/vault.yml"
INVENTORY_FILE="$INFRA_DIR/inventory/hosts.ini"

# _yaml_s: single-quote a value for safe YAML emission.
_yaml_s() { printf "'%s'" "${1//\'/\'\'}"; }

banner "omp VPS provisioning"

# ── 1. Доступ к VPS ───────────────────────────────────────────────────────
stage "VPS: адрес и SSH"
say "Нужен свежий Ubuntu-сервер с root-доступом по SSH."
ask VPS_HOST "IP-адрес VPS:"
ask VPS_USER "SSH-пользователь первого прогона [root]:"
VPS_USER="${VPS_USER:-root}"
ask SSH_PUBKEY "Путь к публичному SSH-ключу [~/.ssh/id_ed25519.pub]:"
SSH_PUBKEY="${SSH_PUBKEY:-~/.ssh/id_ed25519.pub}"
if [[ ! -f "${SSH_PUBKEY/#\~/$HOME}" ]]; then
  warn "ключ ${SSH_PUBKEY} не найден — сгенерируй: ssh-keygen -t ed25519"
  pause "Сделай это и нажми Enter"
fi
cat > "$INVENTORY_FILE" <<INV
[omp_vps]
vps ansible_host=${VPS_HOST} ansible_user=${VPS_USER}

[omp_vps:vars]
ansible_python_interpreter=/usr/bin/python3
INV
printf '  %s✓ wrote%s %s\n' "$GREEN" "$RESET" "$INVENTORY_FILE"
write_env VPS_HOST "$VPS_HOST"
write_env SSH_PUBKEY "$SSH_PUBKEY"
note "После первого прогона root будет закрыт; поменяй ansible_user на deploy."

# ── 2. Домен и DNS ────────────────────────────────────────────────────────
stage "Домен: A-запись"
say "Один домен обслуживает всех пользователей; экземпляры разведены по портам."
ask OMP_DOMAIN "Домен (например agents.example.com):"
ask CADDY_EMAIL "Email для Let's Encrypt:"
step "В панели DNS-регистратора создай A-запись: ${OMP_DOMAIN} → ${VPS_HOST}"
pause "Запись создана? Enter, когда готово"
RESOLVED="$(getent hosts "$OMP_DOMAIN" 2>/dev/null | awk '{print $1}' | head -1 || true)"
if [[ "$RESOLVED" == "$VPS_HOST" ]]; then
  printf '  %s✓%s %s резолвится в %s\n' "$GREEN" "$RESET" "$OMP_DOMAIN" "$RESOLVED"
else
  warn "${OMP_DOMAIN} резолвится в '${RESOLVED:-ничего}', ожидался ${VPS_HOST}."
  warn "ACME не выпустит сертификат, пока DNS не сойдётся. Можно продолжить и перепрогнать позже."
fi
{
  printf 'omp_domain: %s\n' "$(_yaml_s "$OMP_DOMAIN")"
  printf 'caddy_email: %s\n' "$(_yaml_s "$CADDY_EMAIL")"
  printf 'admin_ssh_pubkey_path: %s\n' "$(_yaml_s "$SSH_PUBKEY")"
} > "$OVERRIDES"
printf '  %s✓ wrote%s %s\n' "$GREEN" "$RESET" "$OVERRIDES"
write_env OMP_DOMAIN "$OMP_DOMAIN"

# ── 3. Пользователи ───────────────────────────────────────────────────────
stage "Пользователи ompweb"
say "Каждому: linux-user, свой порт, свой ompweb. Пустое имя — конец ввода."
printf 'omp_users:\n' > "$USERS_FILE"
USER_NAMES=()
while :; do
  ask U_NAME "Имя пользователя (Enter — закончить):"
  [[ -z "$U_NAME" ]] && break
  ask U_PORT "Порт для ${U_NAME} (30000–31000):"
  if ! [[ "$U_PORT" =~ ^[0-9]+$ ]] || (( U_PORT < 30000 || U_PORT > 31000 )); then
    warn "порт вне диапазона 30000–31000 — пропускаю ${U_NAME}"
    continue
  fi
  printf -- '- name: %s\n  port: %s\n' "$(_yaml_s "$U_NAME")" "$U_PORT" >> "$USERS_FILE"
  USER_NAMES+=("$U_NAME")
done
((${#USER_NAMES[@]})) || { warn "нужен хотя бы один пользователь"; exit 1; }
printf '  %s✓ wrote%s %s (%s пользователей)\n' "$GREEN" "$RESET" "$USERS_FILE" "${#USER_NAMES[@]}"

# ── 4. Секреты ────────────────────────────────────────────────────────────
stage "Секреты: пароли и мониторинг"
say "Пароли веб-входа ompweb для каждого пользователя."
{
  printf 'omp_web_passwords:\n'
  for u in "${USER_NAMES[@]}"; do
    ask_secret "PW_${u}" "Пароль для ${u} (один на ompweb и filebrowser):"
    eval "v=\$PW_${u}"
    printf '  %s: %s\n' "$u" "$(_yaml_s "$v")"
  done
  ask MON_PROM_URL "URL remote_write Prometheus на центральном сервере:"
  ask MON_LOKI_URL "URL push Loki на центральном сервере:"
  ask_secret MON_USERNAME "Basic-auth user мониторинга (пусто — без auth):"
  ask_secret MON_PASSWORD "Basic-auth password мониторинга:"
  printf 'monitoring_username: %s\n' "$(_yaml_s "$MON_USERNAME")"
  printf 'monitoring_password: %s\n' "$(_yaml_s "$MON_PASSWORD")"
} > "$VAULT_FILE"
chmod 600 "$VAULT_FILE"
{
  printf 'monitoring_prometheus_url: %s\n' "$(_yaml_s "$MON_PROM_URL")"
  printf 'monitoring_loki_url: %s\n' "$(_yaml_s "$MON_LOKI_URL")"
} >> "$OVERRIDES"
printf '  %s✓ wrote%s %s (0600)\n' "$GREEN" "$RESET" "$VAULT_FILE"
if confirm "Зашифровать vault.yml через ansible-vault сейчас?"; then
  ansible-vault encrypt "$VAULT_FILE" || warn "ansible не найден — зашифруй позже вручную"
fi

# ── 5. Запуск ─────────────────────────────────────────────────────────────
stage "Провижининг"
say "Команды для первого прогона (из каталога $INFRA_DIR):"
step "ansible-galaxy collection install -r requirements.yml"
step "ansible-playbook site.yml --ask-vault-pass   # добавь -k, если вход по паролю"
note "Прогон идемпотентен: смело перезапускай при сбоях (напр. DNS ещё не доехал)."
if confirm "Запустить provisioning прямо сейчас?"; then
  (cd "$INFRA_DIR" && ansible-galaxy collection install -r requirements.yml \
    && ansible-playbook site.yml --ask-vault-pass)
fi

finish
